/**
 * The installed `@3fn/core` version, stamped into generated file headers.
 *
 * Generated output carries this instead of a wall-clock time, so the same token source and
 * the same `@3fn/core` produce the same bytes on every run, and a header still says what
 * produced the file (.kiro/issues/2026-10-03-generate-output-not-deterministic.md).
 *
 * Found by walking up from this module to the nearest `package.json` named `@3fn/core`.
 * That holds from `src/` and from compiled `dist/`, in this repository and in a consumer's
 * `node_modules`. If none is found, `'unknown'`: still deterministic.
 */

import * as fs from 'fs';
import * as path from 'path';

const CORE_PACKAGE_NAME = '@3fn/core';

let cached: string | undefined;

export function getCoreVersion(): string {
  if (cached !== undefined) return cached;
  let found = 'unknown';
  let dir = __dirname;
  for (let i = 0; i < 8; i++) {
    const candidate = path.join(dir, 'package.json');
    try {
      if (fs.existsSync(candidate)) {
        const pkg = JSON.parse(fs.readFileSync(candidate, 'utf-8'));
        if (pkg && pkg.name === CORE_PACKAGE_NAME && typeof pkg.version === 'string') {
          found = pkg.version;
          break;
        }
      }
    } catch {
      // Unreadable package.json: keep walking.
    }
    const parent = path.dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  cached = found;
  return found;
}

/** The provenance line generated headers carry in place of a timestamp. */
export function generatedByLine(version: string = getCoreVersion()): string {
  return `Generated by: ${CORE_PACKAGE_NAME} ${version}`;
}
